#include<stdio.h> // preprocessor directive -- it tells the compiler to include the contents of the stdio.h header file, which contains declarations for input/output functions like printf.

int main(){ // main is the entry point of a C program, where execution starts and int is the return type of the main function, which indicates that the function will return an integer value to the operating system upon completion. If the main function returns 0, it typically signifies that the program executed successfully. And if the main function returns a non-zero value, it usually indicates that an error occurred during execution.
    printf("Hello World");
    return 0; // return statement -- it indicates that the main function has completed its execution and returns a value of 0 to the operating system, which typically signifies successful execution.
}

